import React, { useState,useEffect } from "react";
import { Outlet, Link, useNavigate, useLocation } from "react-router-dom";
import {
  FaBookOpen,
  FaChalkboardTeacher,
  FaUserGraduate,
  FaCalendarAlt,
  FaSignOutAlt,
  FaGraduationCap,
  FaTasks,
  FaClipboardList,
  FaQuestionCircle
} from "react-icons/fa";

function MainLayout() {
  const navigate = useNavigate();
  const location = useLocation();

  const userName = localStorage.getItem("user_name");
  const role = localStorage.getItem("role");

  const handleLogout = () => {
    localStorage.clear();
    navigate("/");
  };

  const linkStyle = (path) => ({
    display: "flex",
    alignItems: "center",
    gap: "10px",
    padding: "12px 14px",
    borderRadius: "12px",
    textDecoration: "none",
    color: location.pathname === path ? "#fff" : "#333",
    background: location.pathname === path ? "#7b1fa2" : "transparent",
    fontWeight: "600",
    marginBottom: "10px",
    transition: "0.3s"
  });

  return (
    <div
      style={{
        display: "flex",
        minHeight: "100vh",
        background: "#f5f7fb"
      }}
    >
      <aside
        style={{
          width: "260px",
          background: "#fff",
          padding: "20px",
          boxShadow: "2px 0 12px rgba(0,0,0,0.06)"
        }}
      >
        <div
          style={{
            display: "flex",
            alignItems: "center",
            gap: "10px",
            fontSize: "22px",
            fontWeight: "bold",
            color: "#7b1fa2",
            marginBottom: "30px"
          }}
        >
          <FaGraduationCap />
          LMS
        </div>

        {role === "teacher" && (
          <Link to="/teacher-dashboard" style={linkStyle("/teacher-dashboard")}>
            <FaChalkboardTeacher />
            Teacher Dashboard
          </Link>
        )}

        {role === "student" && (
          <Link to="/student-dashboard" style={linkStyle("/student-dashboard")}>
            <FaUserGraduate />
            Student Dashboard
          </Link>
        )}

        <Link to="/courses" style={linkStyle("/courses")}>
          <FaBookOpen />
          Courses
        </Link>

        {role === "teacher" && (
          <Link
            to="/teacher-assignments"
            style={linkStyle("/teacher-assignments")}
          >
            <FaClipboardList />
            Assignments
          </Link>
        )}

        {role === "student" && (
          <Link
            to="/student-assignments"
            style={linkStyle("/student-assignments")}
          >
            <FaClipboardList />
            Assignments
          </Link>
        )}

        {role === "teacher" && (
          <Link to="/teacher-quiz" style={linkStyle("/teacher-quiz")}>
            <FaQuestionCircle />
            Quiz
          </Link>
        )}

        {role === "student" && (
          <Link to="/student-quiz" style={linkStyle("/student-quiz")}>
            <FaQuestionCircle />
            Quiz
          </Link>
        )}

        {role === "student" && (
          <Link to="/planner" style={linkStyle("/planner")}>
            <FaCalendarAlt />
            Planner
          </Link>
        )}

        {role === "student" && (
          <Link to="/student-dashboard" style={linkStyle("/student-dashboard")}>
            <FaTasks />
            Progress
          </Link>
        )}
        {role === "teacher" && (
        <Link to="/upload-material" style={linkStyle("/upload-material")}>
          <FaClipboardList />
          Upload Notes
        </Link>
        )}

        {role === "student" && (
        <Link to="/materials" style={linkStyle("/materials")}>
         <FaClipboardList />
         Materials
        </Link>
        )}
        <button
          onClick={handleLogout}
          style={{
            marginTop: "25px",
            width: "100%",
            border: "none",
            background: "#e53935",
            color: "#fff",
            padding: "12px",
            borderRadius: "12px",
            fontWeight: "bold",
            cursor: "pointer",
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
            gap: "10px"
          }}
        >
          <FaSignOutAlt />
          Logout
        </button>
      </aside>

      <main style={{ flex: 1, padding: "25px" }}>
        <div
          style={{
            background: "linear-gradient(135deg, #7b1fa2, #512da8)",
            color: "#fff",
            borderRadius: "18px",
            padding: "22px",
            marginBottom: "25px",
            boxShadow: "0 8px 24px rgba(123,31,162,0.25)"
          }}
        >
          <h2 style={{ margin: 0 }}>
            Welcome, {userName || "User"} 👋
          </h2>

          <p style={{ marginTop: "8px", opacity: 0.9 }}>
            {role === "teacher"
              ? "Manage your courses, assignments, quizzes, and teaching activities."
              : "Track your learning, planner, assignments, quizzes, and progress."}
          </p>
        </div>

        <Outlet />
      </main>
    </div>
  );
}

export default MainLayout;
